import lectureSets from "@/data/videos/lecture-sets.json";

/**
 * Whole-lecture clip sets in data/videos/lecture-sets.json, generated by
 * `node scripts/import-lecture-clips.mjs` from each upload-package.json.
 * youtubeVideoId is null until that part is PUBLISHED ("Coming soon").
 */
export type LectureClip = {
  part: number;
  youtubeVideoId: string | null;
  title: string;
  topic: string | null;
  durationSec: number | null;
  summary: string;
};

export type LectureClipSet = {
  lectureId: string;
  course: string;
  semester: string;
  /** ISO date, YYYY-MM-DD. */
  date: string;
  partCount: number;
  clips: LectureClip[];
};

const LECTURE_FILES = lectureSets as LectureClipSet[];

const YOUTUBE_ID = /^[A-Za-z0-9_-]{11}$/;

/** Bad ids become placeholders so a typo never links a wrong video. */
export function normalizeLectureClips(set: LectureClipSet): LectureClip[] {
  return set.clips
    .map((clip) => ({
      ...clip,
      youtubeVideoId:
        clip.youtubeVideoId && YOUTUBE_ID.test(clip.youtubeVideoId) ? clip.youtubeVideoId : null,
    }))
    .sort((a, b) => a.part - b.part);
}

/** Newest lecture first; lectures with no clips at all are left out. */
export function listLectureClipSets(
  files: LectureClipSet[] = LECTURE_FILES,
): LectureClipSet[] {
  return files
    .map((set) => ({ ...set, clips: normalizeLectureClips(set) }))
    .filter((set) => set.clips.length > 0)
    .sort((a, b) => b.date.localeCompare(a.date));
}

export function lectureClipEmbedUrl(clip: LectureClip): string | null {
  if (!clip.youtubeVideoId) return null;
  const params = new URLSearchParams({ autoplay: "1", rel: "0" });
  return `https://www.youtube-nocookie.com/embed/${encodeURIComponent(clip.youtubeVideoId)}?${params.toString()}`;
}

export function lectureHeading(set: LectureClipSet): string {
  const [y, m, d] = set.date.split("-").map(Number);
  const label = new Date(Date.UTC(y!, m! - 1, d!)).toLocaleDateString("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
    timeZone: "UTC",
  });
  return `${set.course} ${set.semester} · ${label}`;
}
